<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/config/config.php';
use App\Core\JsonDatabase; use App\Services\AuthService; use App\Services\LibraryService;
AuthService::requireRole('admin'); $db = new JsonDatabase(STORAGE_PATH); $books = (new LibraryService($db))->books(); $users = $db->all('users'); $transactions = $db->all('transactions'); $title = 'Dashboard Admin'; $assetPrefix = '../'; require dirname(__DIR__) . '/partials/header.php';
?>
<div class="layout"><aside class="sidebar"><h2>Admin Panel</h2><nav><a class="active" href="dashboard.php">Dashboard</a><a href="books.php">Kelola Buku</a><a href="members.php">Kelola Member</a><a href="transactions.php">Transaksi</a></nav></aside><main class="main"><div class="main-header"><h1>Dashboard Admin</h1><a class="btn btn-primary" href="books.php">Tambah buku</a></div><div class="stats"><div class="card"><span class="muted">Jumlah buku</span><strong><?= count($books) ?></strong></div><div class="card"><span class="muted">Jumlah member</span><strong><?= count(array_filter($users, static fn (array $u): bool => ($u['role'] ?? '') === 'member')) ?></strong></div><div class="card"><span class="muted">Total transaksi</span><strong><?= count($transactions) ?></strong></div><div class="card"><span class="muted">Sedang dipinjam</span><strong><?= count(array_filter($transactions, static fn (array $t): bool => ($t['status'] ?? '') === 'Dipinjam')) ?></strong></div></div><section class="section"><div class="section-title"><h2>Transaksi terbaru</h2><a href="transactions.php">Lihat semua</a></div><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Member</th><th>Status</th><th>Jatuh tempo</th></tr></thead><tbody><?php foreach (array_slice(array_reverse($transactions), 0, 5) as $row): ?><tr><td><?= e((string) $row['id']) ?></td><td><?= e((string) $row['member_id']) ?></td><td><span class="badge"><?= e((string) $row['status']) ?></span></td><td><?= e((string) $row['due_at']) ?></td></tr><?php endforeach; ?><?php if (!$transactions): ?><tr><td colspan="4" class="empty">Belum ada transaksi.</td></tr><?php endif; ?></tbody></table></div></section></main></div>
<?php $assetPrefix = '../'; require dirname(__DIR__) . '/partials/footer.php'; ?>
